const MOD = 1000000007;

function solve() {
    const input = require('fs').readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length === 0) return;
    const x = parseInt(input[0], 10);
    const n = parseInt(input[1], 10);

    const prime_factors = getPrimeFactors(x);

    let result = 1;
    for (const p of prime_factors) {
        let power_p = 0;
        let temp_n = n;
        while (temp_n > 0) {
            temp_n = Math.floor(temp_n / p);
            power_p += temp_n;
        }
        result = (result * modPow(p, power_p, MOD)) % MOD;
    }

    console.log(result);
}

function getPrimeFactors(num) {
    const factors = new Set();
    let n = num;
    for (let i = 2; i * i <= n; i++) {
        if (n % i === 0) {
            factors.add(i);
            while (n % i === 0) {
                n = Math.floor(n / i);
            }
        }
    }
    if (n > 1) {
        factors.add(n);
    }
    return Array.from(factors);
}

function modPow(base, exp, mod) {
    let res = 1;
    base = base % mod;
    while (exp > 0) {
        if (exp % 2 === 1) {
            res = (res * base) % mod;
        }
        base = (base * base) % mod;
        exp = Math.floor(exp / 2);
    }
    return res;
}

solve();
